// The JSON files under testdata/ are generated by tests/parity/gen_stats_vectors.py,
// which calls CPython 3.15 and the Python reference implementation in
// telemetry_common.py. Every float is stored with float.hex() so the vectors
// round-trip exactly through strconv.ParseFloat.

func loadVectors[T any](t *testing.T, name string) T {
	t.Helper()
	path := filepath.Join("testdata", name)
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read vectors %s: %v", path, err)
	}
	var out T
	if err := json.Unmarshal(raw, &out); err != nil {
		t.Fatalf("parse vectors %s: %v", path, err)
	}
	return out
}

func vecFloat(t *testing.T, s string) float64 {
	t.Helper()
	switch strings.ToLower(s) {
	case "inf", "+inf", "infinity", "+infinity":
		return math.Inf(1)
	case "-inf", "-infinity":
		return math.Inf(-1)
	case "nan":
		return math.NaN()
	}
	v, err := strconv.ParseFloat(s, 64)
	if err != nil {
		t.Fatalf("invalid vector float %q: %v", s, err)
	}
	return v
}

func vecFloats(t *testing.T, values []string) []float64 {
	t.Helper()
	out := make([]float64, len(values))
	for i, s := range values {
		out[i] = vecFloat(t, s)
	}
	return out
}

// sameFloat reports bit equality, so -0.0 and 0.0 are distinct; NaNs match
// each other regardless of payload.
func sameFloat(a, b float64) bool {
	if math.IsNaN(a) || math.IsNaN(b) {
		return math.IsNaN(a) && math.IsNaN(b)
	}
	return math.Float64bits(a) == math.Float64bits(b)
}

func describeFloat(v float64) string {
	if math.IsNaN(v) {
		return "nan"
	}
	return fmt.Sprintf("%v (%016x)", v, math.Float64bits(v))
}

func requireFloat(t *testing.T, label string, got, want float64) {
	t.Helper()
	if !sameFloat(got, want) {
		t.Errorf("%s = %s, want %s", label, describeFloat(got), describeFloat(want))
	}
}

func TestPyRoundVectors(t *testing.T) {
	file := loadVectors[struct {
		Cases []struct {
			X       string `json:"x"`
			NDigits int    `json:"ndigits"`
			Want    string `json:"want"`
		} `json:"cases"`
	}](t, "pyround.json")

	for i, c := range file.Cases {
		x := vecFloat(t, c.X)
		want := vecFloat(t, c.Want)
		got := PyRound(x, c.NDigits)
		if !sameFloat(got, want) {
			t.Fatalf("case %d: PyRound(%s, %d) = %s, want %s",
				i, describeFloat(x), c.NDigits, describeFloat(got), describeFloat(want))
		}
	}
	if len(file.Cases) < 500 {
		t.Fatalf("pyround vectors look truncated: %d cases", len(file.Cases))
	}
}

func TestFsumVectors(t *testing.T) {
	file := loadVectors[struct {
		Cases []struct {
			Values []string `json:"values"`
			Want   string   `json:"want"`
		} `json:"cases"`
	}](t, "fsum.json")

	for i, c := range file.Cases {
		values := vecFloats(t, c.Values)
		got := Fsum(values)
		want := vecFloat(t, c.Want)
		if !sameFloat(got, want) {
			t.Fatalf("case %d: Fsum(%v) = %s, want %s",
				i, c.Values, describeFloat(got), describeFloat(want))
		}
	}
}

