func TestPercentileVectors(t *testing.T) {
	file := loadVectors[struct {
		Cases []struct {
			Values []string `json:"values"`
			P      float64  `json:"p"`
			Want   *string  `json:"want"`
		} `json:"cases"`
	}](t, "percentile.json")

	for i, c := range file.Cases {
		values := vecFloats(t, c.Values)
		got, ok := Percentile(values, c.P)
		if c.Want == nil {
			if ok {
				t.Fatalf("case %d: Percentile(%v, %v) = %v, want missing", i, c.Values, c.P, got)
			}
			continue
		}
		if !ok {
			t.Fatalf("case %d: Percentile(%v, %v) reported missing", i, c.Values, c.P)
		}
		requireFloat(t, fmt.Sprintf("case %d Percentile", i), got, vecFloat(t, *c.Want))
	}
}

